   SPW("This is … speaking.", "我就是……（电话里）", ("Hello, this is Anna speaking.", "你好，我是安娜。"), "常用表达"),
   SPW("Can I take a message?", "需要我帮您留言吗？", ("She's out right now. Can I take a message?", "她现在不在，需要留言吗？"), "常用表达"),
